<?php
require_once __DIR__.'/includes/db.php';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';
 if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8){$error='Name, valid email and password of at least 8 characters are required.';}
 else{try{$hash=password_hash($pass,PASSWORD_DEFAULT);$st=$pdo->prepare("INSERT INTO users(name,email,password_hash) VALUES(?,?,?)");$st->execute([$name,$email,$hash]);$_SESSION['user_id']=(int)$pdo->lastInsertId();$_SESSION['user_name']=$name;header('Location: index.php');exit;}catch(Throwable $e){$error='Could not create account. This email may already be registered.';}}
}
